1	use serde::Serialize;
2	use std::future::Future;
3	
4	pub const DEFAULT_LIST_MAX_RESULTS: usize = 2_000;
5	pub const MAX_LIST_RESULTS: usize = 2_000;
6	pub const DEFAULT_SEARCH_MAX_RESULTS: usize = 200;
