27	impl LocalMemoriesBackend {
28	    pub fn from_codex_home(codex_home: &AbsolutePathBuf) -> Self {
29	        Self::from_memory_root(codex_home.join("memories").to_path_buf())
30	    }
31	
32	    pub fn from_memory_root(root: impl Into<PathBuf>) -> Self {
33	        Self { root: root.into() }
34	    }
35	
36	    pub fn root(&self) -> &Path {
37	        &self.root
38	    }
39	
40	    fn resolve_scoped_path(
41	        &self,
42	        relative_path: Option<&str>,
43	    ) -> Result<PathBuf, MemoriesBackendError> {
44	        let Some(relative_path) = relative_path else {
45	            return Ok(self.root.clone());
46	        };
47	        let relative = Path::new(relative_path);
48	        if relative.components().any(|component| {
49	            matches!(
50	                component,
51	                Component::ParentDir | Component::RootDir | Component::Prefix(_)
52	            )
53	        }) {
54	            return Err(MemoriesBackendError::invalid_path(
55	                relative_path,
56	                "must stay within the memories root",
57	            ));
58	        }
59	        Ok(self.root.join(relative))
60	    }
61	
62	    async fn metadata_or_none(
63	        path: &Path,
64	    ) -> Result<Option<std::fs::Metadata>, MemoriesBackendError> {
65	        match tokio::fs::symlink_metadata(path).await {
66	            Ok(metadata) => Ok(Some(metadata)),
67	            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(None),
68	            Err(err) => Err(err.into()),
69	        }
70	    }
71	}
